        SOAPEnvelope envelope = soapPart.getEnvelope();
        envelope.addNamespaceDeclaration("math", serverURI);

        SOAPHeader header = envelope.getHeader();
        SOAPBody soapBody = envelope.getBody();
        SOAPElement soapBodyElem = soapBody.addChildElement("Add", "math");
        SOAPElement soapBodyElem1 = soapBodyElem.addChildElement("a", "math");
        soapBodyElem1.addTextNode("3");
        SOAPElement soapBodyElem2 = soapBodyElem.addChildElement("b", "math");
        soapBodyElem2.addTextNode("5");

        MimeHeaders headers = soapMessage.getMimeHeaders();
        headers.addHeader("SOAPAction", serverURI + "/Add");

        soapMessage.saveChanges();

        /* Imprime la solicitud SOAP */
        System.out.print("Request SOAP Message = ");
        soapMessage.writeTo(System.out);
        System.out.println();

        return soapMessage;
    }

    /**
     * Método para procesar y imprimir la respuesta SOAP
     */
    private static void printSOAPResponse(SOAPMessage soapResponse) throws Exception {
        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        Transformer transformer = transformerFactory.newTransformer();
        Source sourceContent = soapResponse.getSOAPPart().getContent();
        System.out.print("\nResponse SOAP Message = ");
        StreamResult result = new StreamResult(System.out);
        transformer.transform(sourceContent, result);
    }
}

