// Biblioteca usada en este ejemplo para iniciar un servidor en node.js
const express = require('express');
const app = express();
// Biblioteca para el uso de Jason Web Tokens
const jwt = require('jsonwebtoken')

// Middleware que utiliza express para las solicitudes tipo POST o PUT
app.use(express.urlencoded({extended: false}));
app.use(express.json());

// Lo más seguro es tener tu SECRETO en alguna variable de entorno y no
// en tu código fuente, para este ejemplo la asignaremos aquí mismo.
// El SECRETO es una cadena o hash que se que se utiliza
// como llave en la encriptación de tu JWT
const SECRET = "mi_secreto_inseguro";

app.get('/', (req, res) => {
  res.send('Hola mundo!');
});

// Ruta POST para los datos de de autenticación
app.post('/auth', (req, res) => {
  const {username, password} = req.body;

  // Aquí va tu procedimiento de consulta en tu base de datos de usuarios
  // así como tu validación de usuario y contraseña.
  // Asumiendo que la autenticación fue correcta creemos un objeto con
  // la información que quieras agregar a tu token, en este caso solo es
  // el nombre de usuario
  const content = {username: username};

  const accessToken = genAccessToken(content);

  res.header('authorization', accessToken).json({
    message: '¡Usuario autenticado!',
    token: accessToken
  })
});

// Función que genera y retorna un token de acceso
function genAccessToken(content){
  return jwt.sign(content, SECRET, {expiresIn: '5m'});
}

