function validateToken(req, res, next){
  // Recibir token ya sea de headers o una query por url,
  // puedes remover esta última (a partir del ||) una vez hayas terminado
  // de hacer las pruebas correspondientes.
  const accessToken = req.headers['authorization'] || req.query.accessToken;
  if(!accessToken) res.send('Acceso denegado! Token no recibido.');

  jwt.verify(accessToken, SECRET, (err, content) => {
    if(err){
      res.send('Acceso denegado. Token incorrecto o expirado.');
    } else {
      next();
    }
  });
}

// Ruta get para el formulario de autenticación recuerda que debe
// tener como "action" la ruta que determinaste antes
