  res.send(`
    <!DOCTYPE html>
    <html lang="en">
    <head>
      <meta charset="UTF-8">
      <title>Login</title>
    </head>
    <body>
      <form action="/auth" method="post">
        Nombre de usuario: <input type="text" name="user" /><br>
        Contraseña: <input type="password" name="password" /><br>
        <input type="submit" value="Iniciar sesión" />
      </form>
    </body>
    </html>
    `);
});

